/// <summary>
/// PaffH 12.12.24
/// </summary>
/// <param name = "_prodParmRelease">ProdParmRelease</param>
public static void constructFromProdUpdRelease(ProdParmRelease _prodParmRelease)
{
    NDXSSRSReportProdTableProdIdentController controller = new NDXSSRSReportProdTableProdIdentController();
    ProdTable prodTable = _prodParmRelease.prodTable();
    controller.parmReportName(ssrsReportStr(NDXProdIdent, Report));
    controller.parmProdTable(prodTable);
    controller.parmProdParmRelease(_prodParmRelease);
    controller.startOperation();
}

/// <summary>
/// PaffH 13.12.24
/// </summary>
/// <param name = "_prodParmStartUp">ProdParmStartUp</param>
public static void constructFromProdUpdStartUp(ProdParmStartUp _prodParmStartUp)
{
    NDXSSRSReportProdTableProdIdentController controller = new NDXSSRSReportProdTableProdIdentController();
    ProdTable prodTable = _prodParmStartUp.prodTable();
    controller.parmReportName(ssrsReportStr(NDXProdIdent, Report));
    controller.parmProdTable(prodTable);
    controller.parmProdParmStartUp(_prodParmStartUp);
    controller.startOperation();
}

/// <summary>
/// PaffH 14.08.24
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    NDXSSRSReportProdTableProdIdentController controller = NDXSSRSReportProdTableProdIdentController::newFromArgs(_args);
    if (_args.callerType() == UtilElementType::Form)
    {
        if (_args.caller() is NDXManualPALabelWizardI)
        {
            NDXManualPALabelWizardI nDXManualPALabelWizard = _args.caller() as NDXManualPALabelWizardI;
            NDXProdIdentControlPanel nDXProdIdentControlPanel = nDXManualPALabelWizard.parmNDXProdIdentControlPanel();
            controller.parmProdIdentControlPanelManual(nDXProdIdentControlPanel.ProdIdentControlPanelManual);
            controller.parmProdIdentManualId(nDXProdIdentControlPanel.ProdIdentManualId);
            NDXManualPALabelWizard sysWizard = nDXManualPALabelWizard.parmSysWizard();
            controller.parmOrderQty(sysWizard.parmOrderQty());
            controller.parmProdIdManualSelected(sysWizard.parmProdIdManualSelected());
        }
    }
    controller.startOperation();
}

/// <summary>
/// PaffH 14.08.24
/// </summary>
/// <param name = "_args">Args</param>
/// <returns>NDXSSRSReportProdTableProdIdentController</returns>
public static NDXSSRSReportProdTableProdIdentController newFromArgs(Args _args)
{
    NDXSSRSReportProdTableProdIdentController controller;
    controller = NDXSSRSReportProdTableProdIdentController::construct();
    controller.parmArgs(_args);
    controller.parmReportName(ssrsReportStr(NDXProdIdent, Report));
    controller.parmLoadFromSysLastValue(false);

    if (_args)
    {
        if (_args.record().RecId)
        {
            switch (_args.dataset())
            {
                case tableNum(ProdTable):
                    controller.parmProdTable(_args.record());
                    break;
                case tableNum(NDXProdIdentControlPanel):
                    controller.parmNDXProdIdentControlPanel(_args.record());
                    break;
            }
        }
    }
    return controller;
}

/// <summary>
/// PaffH 14.08.24
/// last modified: PaffH 13.12.24
/// </summary>
protected void prePromptModifyContract()
{
    NDXSSRSReportProdTableProdIdentContract contract = this.parmReportContract().parmRdpContract() as NDXSSRSReportProdTableProdIdentContract;

    contract.parmProdId(prodIdManualSelected);
    if (prodTable)
    {
        contract.parmProdId(prodTable.ProdId);
        contract.parmOrderQuantity(prodTable.QtySched);
    }
    contract.parmProdIdentControlPanelManual(prodIdentControlPanelManual);
    contract.parmProdIdentManualId(prodIdentManualId);
    if (orderQty)
    {
        contract.parmOrderQuantity(orderQty);
    }
    if (nDXProdIdentControlPanel)
    {
        contract.parmOrderQuantity(nDXProdIdentControlPanel.AnzahlEtiketten);
        contract.parmProdIdentControlPanelManual(nDXProdIdentControlPanel.ProdIdentControlPanelManual);
        if (nDXProdIdentControlPanel.ProdIdentControlPanelManual == NoYes::Yes)
        {
            contract.parmProdIdentManualId(nDXProdIdentControlPanel.ProdIdentManualId);
        }
        else
        {
            contract.parmProdId(nDXProdIdentControlPanel.ProdId);
        }
    }

    // set printSettings from prodParmStartup / prodParmRelease
    if (this.printFromProdUpd())    
    {
        this.parmShowDialog(false);
        if (conLen(this.printDestinationFromProdUpd()) != 0)
        {
            SrsReportDataContract dataContract = this.parmReportContract();
            dataContract.parmPrintSettings(new SRSPrintDestinationSettings(this.printDestinationFromProdUpd()));
        }
    }
    else
    {
        this.parmShowDialog(true);
    }

}

/// <summary>
/// PaffH 12.12.24
/// </summary>
/// <returns>print form prodParmRelease or prodParmStartUp</returns>
private boolean printFromProdUpd()
{
    return prodParmRelease.RecId || prodParmStartUp.RecId;
}

/// <summary>
/// PaffH 12.12.24
/// </summary>
/// <returns>Printsettings</returns>
private container printDestinationFromProdUpd()
{
    container printDestinationCon;
    if (prodParmRelease)
    {
        printDestinationCon = prodParmRelease.NDXSetupPrintProdProdIdent;
    }
    else if (prodParmStartUp)
    {
        printDestinationCon = prodParmStartUp.NDXSetupPrintProdProdIdent;
    }
    return printDestinationCon;
}

/// <summary>
/// PaffH 14.08.24
/// </summary>
public void preRunReport()
{
    NDXSSRSReportProdTableProdIdentContract contract = this.parmReportContract().parmRdpContract() as NDXSSRSReportProdTableProdIdentContract;
    contract.parmProdIdentControlPanelManual(prodIdentControlPanelManual);
    contract.parmProdIdentManualId(prodIdentManualId);
}

